arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve old discriminator property name for existing documents
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve old compound id format ("Blog|1") for existing documents
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // Fix 3: HasIndex throws in EF Core 9 Cosmos provider — removed
        // Cosmos DB indexing is managed via the container's indexing policy (Azure Portal/Bicep)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

arguments.old_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    // Fix 4: Sync I/O no longer supported in EF Core 9 Cosmos provider —
    // ToList() and SaveChanges() now throw. Use async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

